["source_call",["lua","lua/codecompanion/acp/init.lua",["Connection"],"method","flatten_config_options","(?)"],2,"vim
    .iter(opts)
    :map(function(item)
      -- The ACP specification allows options to be grouped
      -- Ref: https://agentclientprotocol.com/protocol/schema#sessionconfigselectgroup
      if item.group then
        return vim.tbl_map(function(val)
          return vim.tbl_extend("force", val, { group = item.name })
        end, item.options or {})
      end
      return { item }
    end)
    :flatten"]

